{
  "API_calls": [],
  "collected_information": {
    "environment_setup": {
      "prerequisites": [
        "Node.js >=18",
        "Git",
        "Docker (Docker Desktop, sign in to Docker app)",
        "OpenAI API key",
        "Editor (e.g., Visual Studio Code)"
      ],
      "setup_commands": {
        "Mac/Linux": [
          "git clone https://github.com/reworkd/AgentGPT.git",
          "cd AgentGPT",
          "./setup.sh"
        ],
        "Windows": [
          "git clone https://github.com/reworkd/AgentGPT.git",
          "cd AgentGPT",
          "./setup.bat"
        ]
      },
      "details": "Setup scripts configure environment variables (see .env.example), database (MySQL via Docker), backend (FastAPI), and frontend (Next.js).",
      "tech_stack": [
        "FastAPI",
        "SQLModel",
        "Pydantic",
        "Next.js 13 with Typescript",
        "Prisma ORM",
        "Planetscale (MySQL-compatible)",
        "Langchain"
      ]
    },
    "dependencies": {
      "management_tool": "Poetry in platform/ directory",
      "commands": ["poetry install", "poetry run python -m reworkd_platform"]
    },
    "docker_commands": {
      "start_services": "docker-compose -f deploy/docker-compose.yml --project-directory . up --build",
      "dev_mode": "docker-compose -f deploy/docker-compose.yml -f deploy/docker-compose.dev.yml --project-directory . up --build"
    },
    "environment_variables": {
      "location": ".env file at root",
      "prefix": "REWORKD_PLATFORM_",
      "examples": {
        "REWORKD_PLATFORM_RELOAD": "True",
        "REWORKD_PLATFORM_PORT": "8000",
        "REWORKD_PLATFORM_ENVIRONMENT": "development"
      }
    },
    "testing_instructions": {
      "docker_test": [
        "docker-compose -f deploy/docker-compose.yml -f deploy/docker-compose.dev.yml --project-directory . run --build --rm api pytest -vv .",
        "docker-compose -f deploy/docker-compose.yml -f deploy/docker-compose.dev.yml --project-directory . down"
      ],
      "local_test": [
        "docker run -p \"3306:3306\" -e \"MYSQL_PASSWORD=reworkd_platform\" -e \"MYSQL_USER=reworkd_platform\" -e \"MYSQL_DATABASE=reworkd_platform\" -e ALLOW_EMPTY_PASSWORD=yes bitnami/mysql:8.0.30",
        "pytest -vv ."
      ]
    },
    "linters_and_quality_tools": [
      "poetry run black .",
      "poetry run autoflake --in-place --remove-duplicate-keys --remove-all-unused-imports -r .",
      "poetry run flake8",
      "poetry run mypy ."
    ],
    "test_coverage_command": "poetry run pytest -vv --cov=\"reworkd_platform\" .",
    "pre_commit_hooks": {
      "install": "pre-commit install",
      "tools": ["black", "mypy", "isort", "flake8"]
    },
    "key_files": {
      "pyproject_toml": "platform/pyproject.toml",
      "poetry_lock": "platform/poetry.lock",
      "test_target": "platform/reworkd_platform/tests/agent/test_open_ai_agent_service.py"
    }
  },
  "terminate": true
}
